-- Disposable native PostgreSQL rollback suite only. Never run against connected providers.
begin;
create temp table settings_results(name text primary key);grant select,insert on settings_results to anon,authenticated;
create function pg_temp.ok(value boolean,label text) returns void language plpgsql as $$begin if value is distinct from true then raise exception 'FAILED %',label;end if;insert into pg_temp.settings_results values(label);end$$;
create function pg_temp.denied(sql text,label text) returns void language plpgsql as $$declare code text;begin begin execute sql;exception when others then get stacked diagnostics code=returned_sqlstate;end;if code is distinct from '42501' then raise exception 'FAILED % expected 42501 got %',label,code;end if;insert into pg_temp.settings_results values(label);end$$;
create function pg_temp.claim(n integer) returns void language sql as $$select set_config('request.jwt.claims',jsonb_build_object('iss','https://gmvouqgjbtbkbhrdruzu.supabase.co/auth/v1','aud','authenticated','role','authenticated','sub','10000000-0000-0000-0000-'||lpad(n::text,12,'0'))::text,true)::void$$;
set local role anon;
select pg_temp.denied($q$select public.notification_command('preferences','{}')$q$,'anonymous cannot load settings');
reset role;set local role authenticated;select pg_temp.claim(5);
select pg_temp.ok(public.notification_command('preferences','{}')='[]'::jsonb,'new learner has no fabricated preference rows');
select public.notification_command('preference','{"event":"exam_released","inApp":false,"push":false}');
select pg_temp.ok(public.notification_command('preferences','{}') @> '[{"event_type":"exam_released","in_app":false,"push":false}]','save is persisted by actual identity-bound RPC');
select public.notification_command('preference','{"event":"lesson_published","inApp":true,"push":false}');
select public.notification_command('preference','{"event":"exam_released","inApp":false,"push":false}');
select pg_temp.ok(jsonb_array_length(public.notification_command('preferences','{}'))=2,'independent events preserved and repeated saves idempotent');
select pg_temp.denied($q$update public.notification_preferences set in_app=true$q$,'direct preference writes blocked');
select pg_temp.claim(6);
select pg_temp.ok(public.notification_command('preferences','{}')='[]'::jsonb,'other student cannot read original student settings');
select pg_temp.ok((select count(*)=0 from public.notification_preferences),'RLS hides peer notification preference rows');
select public.notification_command('preference','{"event":"exam_released","inApp":true,"push":false,"user_id":"10000000-0000-0000-0000-000000000005"}');
select pg_temp.claim(5);
select pg_temp.ok(public.notification_command('preferences','{}') @> '[{"event_type":"exam_released","in_app":false}]','forged direct RPC user_id cannot retarget another identity');
reset role;set local role authenticated;select pg_temp.claim(5);
select pg_temp.ok(public.notification_command('preferences','{}') @> '[{"event_type":"exam_released","in_app":false}]','fresh role/session context restores persisted values');
reset role;
select pg_temp.ok((select count(*)=2 from public.notification_preferences where user_id='10000000-0000-0000-0000-000000000005'),'privileged persisted-state verification confirms two own rows');
select pg_temp.ok(not has_function_privilege('authenticated','public.create_organization(text,text)','execute'),'organization provisioning security unchanged');
select count(*) settings_tests from pg_temp.settings_results;
rollback;
